import json
import urllib.request
import math

URL = "http://loophole-sim:8000/mcp"
HEADERS = {"Content-Type": "application/json", "Accept": "application/json, text/event-stream"}

def call_tool(name, arguments={}):
    data = json.dumps({
        "jsonrpc": "2.0",
        "id": 1,
        "method": "tools/call",
        "params": {"name": name, "arguments": arguments}
    }).encode()
    req = urllib.request.Request(URL, data=data, headers=HEADERS, method="POST")
    with urllib.request.urlopen(req) as resp:
        body = resp.read().decode()
        for line in body.splitlines():
            if line.startswith("data: "):
                res = json.loads(line[6:])
                if "error" in res:
                    raise RuntimeError(f"MCP error: {res['error']}")
                txt = res["result"]["content"][0]["text"]
                try:
                    return json.loads(txt)
                except:
                    return txt
    raise RuntimeError(f"Unexpected response: {body}")

def get_state():
    return call_tool("get_state")

def grab(handle, node):
    res = call_tool("grab", {"handle": handle, "node": node})
    print(f"GRAB({handle}, {node}) -> {res}")
    return res

def move(handle, dx, dy, dz):
    # clamp or verify <= 30
    assert abs(dx) <= 30.0001 and abs(dy) <= 30.0001 and abs(dz) <= 30.0001, f"Move too big: {dx}, {dy}, {dz}"
    res = call_tool("move", {"handle": handle, "dx": round(dx, 2), "dy": round(dy, 2), "dz": round(dz, 2)})
    print(f"MOVE({handle}, {dx:.1f}, {dy:.1f}, {dz:.1f}) -> {res}")
    return res

def release(handle):
    res = call_tool("release", {"handle": handle})
    print(f"RELEASE({handle}) -> {res}")
    return res

